#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int main() {
    long long inputNumber;
    std::cin >> inputNumber;

    static std::vector<long long> ONES(17);
    ONES[1] = 1;
    for (int i = 2; i < 17; ++i) {
        ONES[i] = 10 * ONES[i - 1] + 1;
    }

    std::function<long long(long long, int)> recurse = [&](long long x, int len) -> long long {
        x = std::abs(x);
        if (x % ONES[len] == 0) {
            return (x / ONES[len]) * len;
        }
        long long lowerBound = x / ONES[len];
        long long upperBound = lowerBound + 1;

        long long candidate1 = lowerBound * len + recurse(x - lowerBound * ONES[len], len - 1);
        long long candidate2 = upperBound * len + recurse(upperBound * ONES[len] - x, len - 1);
        return std::min(candidate1, candidate2);
    };

    long long answer = recurse(inputNumber, 16);
    std::cout << answer << std::endl;

    return 0;
}
